<script>
(function(){
  'use strict';
  const token=localStorage.getItem('belm_tech_token')||'';
  const root=document.getElementById('assignedCustomerRoot');
  const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]));
  const val=(o,...keys)=>{for(const k of keys)if(o&&o[k]!=null&&o[k]!=='')return o[k];return''};
  const bool=v=>v===true||v===1||v==='1'||String(v||'').toLowerCase()==='true';
  const status=m=>{const s=String(val(m,'status','machineStatus','machine_status')||'UNKNOWN').toUpperCase();if(s.includes('RED')||s.includes('CRITICAL'))return['red','RED'];if(s.includes('YELLOW')||s.includes('ATTENTION')||s.includes('WARNING'))return['yellow','ATTENTION'];if(s.includes('GREEN')||s.includes('NORMAL')||s.includes('OK'))return['green','NORMAL'];return['neutral','NOT CHECKED']};
  const fmt=v=>{if(!v)return'';const d=new Date(v);return Number.isNaN(d.getTime())?String(v):d.toLocaleString('en-GB',{day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit'})};
  function customerScope(){return sessionStorage.getItem('belm_tech_customer_scope')||''}
  async function api(url,options={}){const scope=customerScope();const headers={Authorization:'Bearer '+token,...(scope?{'X-BELM-Customer-Scope':scope}:{}),...(options.headers||{})};const init={cache:'no-store',...options,headers};if(init.body&&typeof init.body!=='string'){init.headers={'Content-Type':'application/json',...headers};init.body=JSON.stringify(init.body)}const r=await fetch(url,init);const d=await r.json().catch(()=>({}));if(!r.ok)throw new Error(d.error||'Could not load assigned customer.');return d}
  function uniqueMachines(rows){const seen=new Set();return (Array.isArray(rows)?rows:[]).filter(m=>{const key=String(val(m,'id')||val(m,'serialNumber','serial_number')||val(m,'fleetNumber','fleet_number')||val(m,'regNumber','reg_number')||'').trim().toLowerCase();if(!key||seen.has(key))return false;seen.add(key);return true})}
  function machineLabel(m){return val(m,'label')||[val(m,'brand'),val(m,'model')].filter(Boolean).join(' ')||val(m,'machineType','machine_type')||'Machine'}
  function enrichMachines(report,customer,machines){
    const checklists=Array.isArray(report?.checklists)?report.checklists:[];
    const operators=Array.isArray(report?.operatorReports)?report.operatorReports:[];
    const services=Array.isArray(report?.maintenanceSummary)?report.maintenanceSummary:[];
    const jobs=Array.isArray(report?.jobCards)?report.jobCards:[];
    return machines.map(machine=>{
      const id=String(val(machine,'id'));
      const latestChecklist=checklists.find(row=>String(row.machineId)===id)||null;
      const latestOperator=operators.find(row=>String(row.machineId)===id&&String(row.status||'').toUpperCase()!=='RESOLVED')||operators.find(row=>String(row.machineId)===id)||null;
      const service=services.find(row=>String(row.machineId)===id)||null;
      const openJob=jobs.find(row=>String(row.machineId)===id&&!['COMPLETED','CANCELLED'].includes(String(row.status||'').toUpperCase()))||null;
      const summaryLevel=String(latestChecklist?.status||val(machine,'status')||service?.level||'UNKNOWN').toUpperCase();
      const operatorMessage=latestOperator?.message?String(latestOperator.message):'No operator message reported yet.';
      const alertMessage=latestOperator?.message?String(latestOperator.message):(openJob?.faultDescription||openJob?.title||'');
      let serviceText='Service due: not available';
      if(service?.statusText)serviceText=String(service.statusText);
      else if(service?.dueHour!=null)serviceText='Next service: '+service.dueHour+' hrs';
      let activityLabel='Working';
      const jobStatus=String(openJob?.status||'').toUpperCase();
      if(jobStatus==='TESTING')activityLabel='Testing';
      else if(jobStatus==='WAITING_FOR_PARTS')activityLabel='Maintenance';
      else if(openJob)activityLabel='Check-up';
      return {...machine,customerName:customer?.name||'Customer',summaryLevel,operatorMessage,alertMessage,serviceText,activityLabel};
    });
  }
  function cardLevel(m){const raw=String(val(m,'summaryLevel','checkStatus','status')||'').toUpperCase();if(raw.includes('RED')||raw.includes('CRITICAL'))return'red';if(raw.includes('YELLOW')||raw.includes('ATTENTION')||raw.includes('WARNING'))return'yellow';if(raw.includes('GREEN')||raw.includes('NORMAL')||raw.includes('OK'))return'green';return'neutral'}
  function conditionText(level){return level==='red'?"Red — Don't operate":level==='yellow'?'Yellow — Attention':level==='green'?'Green — Normal':'Not checked'}
  function machineCard(m){const id=val(m,'id'),label=machineLabel(m),fleet=val(m,'fleetNumber','fleet_number')||'—',serial=val(m,'serialNumber','serial_number')||'—',reg=val(m,'regNumber','reg_number')||'—',level=cardLevel(m),customer=val(m,'customerName')||'Customer',operator=val(m,'operatorMessage')||'No operator message reported yet.',alert=val(m,'alertMessage')||(level==='red'?'Machine requires immediate attention.':level==='yellow'?'Machine requires attention.':'Machine condition normal.'),service=val(m,'serviceText')||'Service due: not available',activity=val(m,'activityLabel')||'Working',activityClass=String(activity).toLowerCase().includes('ground')?'is-grounded':String(activity).toLowerCase().includes('check')?'is-checkup':String(activity).toLowerCase().includes('service')||String(activity).toLowerCase().includes('maint')?'is-service':'';return `<article class="assigned-machine-card tech-summary-card level-${level}" data-machine-id="${esc(id)}" data-summary-photo-only="1"><section class="tech-machine-summary"><div class="tech-machine-summary-head"><span class="tech-machine-summary-fleet">${esc(fleet)}</span><span class="tech-machine-summary-activity ${activityClass}">${esc(activity)}</span></div><div class="belm-machine-summary-visual"><span>${esc(label)}</span></div><h3>${esc(label)}</h3><p class="tech-machine-summary-meta">Machine details</p><div class="tech-machine-summary-facts"><div class="tech-machine-summary-fact"><span>Customer</span><b>${esc(customer)}</b></div><div class="tech-machine-summary-fact"><span>Condition</span><b>${esc(conditionText(level))}</b></div><div class="tech-machine-summary-fact"><span>Operator / Message</span><b>${esc(operator)}</b></div><div class="tech-machine-summary-fact alert-box"><span>Alert</span><b>${esc(alert)}</b></div></div><div class="tech-machine-summary-service">${esc(service)}</div><div class="tech-machine-summary-bar"><i></i></div><div class="tech-machine-summary-actions"><a class="tech-machine-summary-check" href="/concept-dashboards/08-daily-checklist/?actor=technician&machine=${encodeURIComponent(id)}">Check Up</a><button type="button" class="tech-machine-summary-reports" data-machine-reports="${esc(id)}">Reports</button><a class="tech-machine-summary-job" href="/technician-job-cards/?machine=${encodeURIComponent(id)}">Job Card</a><button type="button" class="tech-machine-summary-view" data-machine-details="${esc(id)}">View Details</button></div></section><section class="tech-machine-detail-v826"><h3>${esc(label)}</h3><div class="tech-machine-detail-grid"><div><span>Fleet No.</span><b>${esc(fleet)}</b></div><div><span>Serial No.</span><b>${esc(serial)}</b></div><div><span>Registration</span><b>${esc(reg)}</b></div></div><div class="tech-machine-detail-actions"><button type="button" data-machine-summary-back>← Back to Machine Card</button></div></section></article>`}
  function readonlyToggle(label,on,stateOn,stateOff){return `<div class="tech-readonly-toggle ${on?'on':'off'}"><span class="toggle-label">${esc(label)}</span><span class="tech-toggle-track" aria-hidden="true"></span><span class="toggle-state">${esc(on?stateOn:stateOff)}</span></div>`}
  const communicationSlots=[{key:'service',title:'Service Reminder',empty:'No new service reminder.',match:/service reminder|service due|maintenance due|service overdue|next service|scheduled service/i},{key:'operator',title:'Operator Report',empty:'No new operator report.',match:/operator report|operator|operation report|daily check|daily checklist/i},{key:'job',title:'Job Card Alert',empty:'No new job card alert.',match:/job card|jobcard|technician dispatch|assigned job|diagnosis report|waiting for spare|testing|completed/i}];
  const communicationText=item=>[item?.subject,item?.title,item?.message,item?.body,item?.description,item?.type,item?.category].filter(Boolean).join(' ');const randomItem=items=>items[Math.floor(Math.random()*items.length)];
  function communicationCard(slot,items){const matches=(Array.isArray(items)?items:[]).filter(item=>slot.match.test(communicationText(item)));const item=matches.length?randomItem(matches):null;if(!item)return `<article class="technician-customer-feed-row is-placeholder feed-${slot.key}"><b>${esc(slot.title)}</b><p>${esc(slot.empty)}</p><small>Standing alert slot</small></article>`;return `<article class="technician-customer-feed-row feed-${slot.key}"><b>${esc(slot.title)}</b><p>${esc(item.message||item.body||item.description||item.subject||item.title||'New message available.')}</p><small>${esc(fmt(item.createdAt||item.created_at||item.updatedAt||item.updated_at))}</small></article>`}
  let communicationOrder=[],communicationIndex=0;function nextCommunicationSlot(){if(communicationIndex>=communicationOrder.length){communicationOrder=[...communicationSlots];for(let i=communicationOrder.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[communicationOrder[i],communicationOrder[j]]=[communicationOrder[j],communicationOrder[i]]}communicationIndex=0}return communicationOrder[communicationIndex++]}
  function startCommunicationRotation(items){const body=document.getElementById('communicationFeedBody');if(!body)return;const render=()=>{body.innerHTML=communicationCard(nextCommunicationSlot(),items)};render();window.setInterval(render,9000)}
  function jobNeedsAttention(job){const s=String(job?.status||'').toUpperCase();const stage=String(job?.current_stage||job?.currentStage||'').toUpperCase();if(['COMPLETED','CANCELLED'].includes(s)||stage==='COMPLETED')return false;const explicitNew=['ASSIGNED','OPEN','OPENED','NEW','DISPATCHED','PENDING_RECEIVE'].includes(s)||['ASSIGNED','OPENED','DISPATCHED','PENDING_RECEIVE'].includes(stage);if(explicitNew)return true;const started=Boolean(job?.started_at||job?.startedAt);const hasProgress=Boolean(String(job?.diagnosis||'').trim()||String(job?.work_done||job?.workDone||'').trim()||String(job?.test_result||job?.testResult||'').trim());return !started&&!hasProgress&&s!=='RECEIVED'&&stage!=='RECEIVED'}
  async function syncJobCardAlert(){const nav=document.getElementById('myJobCardsNav');if(!nav||!token)return;try{const jobs=await api('/api/breakdown-workflow/technician-jobs');const count=Array.isArray(jobs)?jobs.filter(jobNeedsAttention).length:0;nav.classList.toggle('job-card-alert-blink',count>0)}catch(_){nav.classList.remove('job-card-alert-blink')}}
  function startJobCardAlertWatch(){syncJobCardAlert();window.setInterval(syncJobCardAlert,15000)}
  const reportCategories=[['checklists','Checklist Report','Daily, inspection and check-up records'],['operator','Operator Report','Operator messages and condition records'],['fuel','Fuel Report','Fuel quantity, cost and consumption'],['job-cards','Job Card Report','Assigned, active and completed Job Cards'],['maintenance','Maintenance Report','Service and maintenance history']];
  function periodParams(card,category,machineId,requireDates){const from=card.querySelector('[data-from]').value||'',to=card.querySelector('[data-to]').value||'';if(requireDates&&(!from||!to))throw new Error('Select both From and To dates first.');if(from&&to&&from>to)throw new Error('From date cannot be after To date.');const p=new URLSearchParams({category,machineId:String(machineId)});if(from)p.set('from',from);if(to)p.set('to',to);return p}
  async function downloadReport(url,name,button){const old=button.textContent;button.disabled=true;button.textContent='Preparing...';try{const r=await fetch(url,{cache:'no-store',headers:{Authorization:'Bearer '+token}});if(!r.ok){const e=await r.json().catch(()=>({}));throw new Error(e.error||`Download failed (${r.status})`)}const blob=await r.blob(),href=URL.createObjectURL(blob),a=document.createElement('a');a.href=href;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(href),60000)}finally{button.disabled=false;button.textContent=old}}
  function openReports(machine){const dialog=document.getElementById('techMachineReportsDialog'),id=val(machine,'id'),label=machineLabel(machine),fleet=val(machine,'fleetNumber','fleet_number')||'—';dialog.innerHTML=`<div class="tmr-head"><div><small>MACHINE GENERAL REPORT</small><h2>${esc(label)}</h2><p>Fleet ${esc(fleet)} · Select report type and date range.</p></div><button class="tmr-close" type="button">×</button></div><div class="tmr-body"><div class="tmr-grid">${reportCategories.map(([key,title,note])=>`<article class="tmr-card" data-category="${key}"><h3>${esc(title)}</h3><p>${esc(note)}</p><div class="tmr-period"><label>From<input type="date" data-from></label><label>To<input type="date" data-to></label></div><div class="tmr-actions"><button type="button" class="tmr-view" data-view>VIEW</button><button type="button" class="tmr-pdf" data-pdf disabled>DOWNLOAD PDF</button><button type="button" class="tmr-csv" data-csv disabled>DOWNLOAD CSV</button></div><p class="tmr-note">Choose both dates to enable PDF/CSV.</p></article>`).join('')}</div></div>`;dialog.querySelector('.tmr-close').onclick=()=>dialog.close();dialog.querySelectorAll('.tmr-card').forEach(card=>{const category=card.dataset.category,from=card.querySelector('[data-from]'),to=card.querySelector('[data-to]'),pdf=card.querySelector('[data-pdf]'),csv=card.querySelector('[data-csv]'),note=card.querySelector('.tmr-note');const sync=()=>{const ready=Boolean(from.value&&to.value);pdf.disabled=!ready;csv.disabled=!ready;note.textContent=ready?'Date range selected — download is ready.':'Choose both dates to enable PDF/CSV.'};from.addEventListener('change',sync);to.addEventListener('change',sync);card.querySelector('[data-view]').onclick=()=>{try{location.href=`/tech-report/?${periodParams(card,category,id,false).toString()}`}catch(e){alert(e.message)}};pdf.onclick=e=>{try{const p=periodParams(card,category,id,true);downloadReport(`/api/checklist-reports/technician-general/pdf?${p}`,`BELM-${label}-${category}-${from.value}-to-${to.value}.pdf`,e.currentTarget).catch(x=>alert(x.message))}catch(x){alert(x.message)}};csv.onclick=e=>{try{const p=periodParams(card,category,id,true);downloadReport(`/api/checklist-reports/technician-general/csv?${p}`,`BELM-${label}-${category}-${from.value}-to-${to.value}.csv`,e.currentTarget).catch(x=>alert(x.message))}catch(x){alert(x.message)}};sync()});if(!dialog.open)dialog.showModal()}
  function bindMachineBoard(machines){const panel=document.getElementById('customerMachinePanel');if(!panel)return;panel.addEventListener('click',e=>{const details=e.target.closest('[data-machine-details]');if(details){const card=details.closest('.tech-summary-card');card?.classList.add('is-detail');card?.scrollIntoView({behavior:'smooth',block:'nearest'});return}const back=e.target.closest('[data-machine-summary-back]');if(back){const card=back.closest('.tech-summary-card');card?.classList.remove('is-detail');card?.scrollIntoView({behavior:'smooth',block:'nearest'});return}const reports=e.target.closest('[data-machine-reports]');if(reports){const machine=machines.find(m=>String(val(m,'id'))===String(reports.getAttribute('data-machine-reports')));if(machine)openReports(machine)}})}
  function renderCodeGate(message=''){sessionStorage.removeItem('belm_tech_customer_scope');root.className='';root.innerHTML=`<section class="customer-code-gate"><small>BELM TECHNICIAN ONLY · CUSTOMER SITE VERIFICATION</small><h2>Enter Customer Name</h2><p>Use the registered Customer / Company Name as the access code for the customer site assigned to you. Example: <b>J LTD</b>. Customer names and machines stay hidden until verification succeeds.</p><form id="customerCodeForm" class="customer-code-form" autocomplete="off"><input id="customerCodeInput" name="customerCode" maxlength="120" placeholder="J LTD" aria-label="Customer Name / Customer Code" required><button type="submit">OPEN MACHINES</button></form><p id="customerCodeError" class="customer-code-error">${esc(message)}</p><p class="customer-code-security">Customer Name + Technician assignment are both required. Entering another company's name will not open that customer's machines.</p></section>`;const form=document.getElementById('customerCodeForm'),input=document.getElementById('customerCodeInput'),error=document.getElementById('customerCodeError');input?.focus();form?.addEventListener('submit',async e=>{e.preventDefault();const code=String(input.value||'').trim();if(!code){error.textContent='Enter the registered Customer / Company Name.';return}const button=form.querySelector('button');button.disabled=true;button.textContent='VERIFYING...';error.textContent='';try{const verified=await api('/api/checklist-reports/technician-customer-access',{method:'POST',body:{customerCode:code}});if(verified?.scopeToken)sessionStorage.setItem('belm_tech_customer_scope',verified.scopeToken);await loadAssignedCustomer()}catch(err){error.textContent=err.message||'Customer Name / Code was not accepted.';input.select()}finally{button.disabled=false;button.textContent='OPEN MACHINES'}})}
  async function loadAssignedCustomer(){root.className='assigned-loading';root.textContent='Loading verified customer machines…';try{const report=await api('/api/checklist-reports/technician-general');let customer={...(report.customer||{})},machines=enrichMachines(report,report.customer||{},uniqueMachines(report.machines));let comm=[];const active=bool(val(customer,'isActive','is_active')??true),belmProvider=!bool(val(customer,'isMachineryAdmin','is_machinery_admin'));root.className='';root.innerHTML=`<section class="technician-customer-card" id="technicianCustomerWorkspace"><div class="technician-customer-summary-v824" id="customerSummaryView"><div class="technician-customer-head"><div class="technician-customer-title"><p class="technician-customer-eyebrow">Verified Customer</p><h2>${esc(customer.name)}</h2><div class="technician-customer-contact"><div><span>Phone</span><b>${esc(val(customer,'phone','contact')||'Not recorded')}</b></div><div><span>Email</span><b>${esc(val(customer,'email')||'Not recorded')}</b></div><div><span>Address</span><b>${esc(val(customer,'address')||'Not recorded')}</b></div></div><div class="technician-customer-controls"><span class="technician-customer-badge ${active?'':'off'}">${active?'Active':'Inactive'}</span>${readonlyToggle(customer.name,belmProvider,'BELM ON','CUSTOMER ON')}${readonlyToggle('Non-payment',active,'PORTAL ON','PORTAL OFF')}</div></div></div><section class="technician-customer-feed"><div class="technician-customer-feed-head"><strong>Communication<br>history</strong><a href="communication.php">View all</a></div><div class="technician-customer-feed-body" id="communicationFeedBody" aria-live="polite"></div></section><div class="technician-customer-actions-v823"><button type="button" class="technician-customer-view-machines" id="viewCustomerMachines">VIEW MACHINE${machines.length===1?'':'S'} · ${machines.length}</button><button type="button" class="technician-customer-change" id="changeCustomerCodeTop">LOCK / CHANGE CUSTOMER</button></div><div class="technician-customer-note">Customer Name verified for this BELM Technician session. Press VIEW MACHINE to replace this summary with the customer's machine cards.</div></div><section id="customerMachinePanel" class="customer-machine-view-v824" hidden><div class="machine-board-head"><div><small>VERIFIED CUSTOMER MACHINES</small><h2>${esc(customer.name)} Machines</h2><p>${machines.length} registered machine${machines.length===1?'':'s'} · customer summary is hidden while this view is open.</p></div><button type="button" class="machine-board-back" id="closeCustomerMachines">← BACK TO CUSTOMER</button></div><div class="assigned-machine-grid">${machines.length?machines.map(machineCard).join(''):'<div class="assigned-empty">No registered machines found for this customer.</div>'}</div></section></section>`;const workspace=document.getElementById('technicianCustomerWorkspace'),machinePanel=document.getElementById('customerMachinePanel');document.getElementById('viewCustomerMachines')?.addEventListener('click',()=>{machinePanel.hidden=false;machinePanel.classList.add('is-open');workspace.classList.add('machine-mode');workspace.scrollIntoView({behavior:'smooth',block:'start'})});document.getElementById('closeCustomerMachines')?.addEventListener('click',()=>{machinePanel.hidden=true;machinePanel.classList.remove('is-open');workspace.classList.remove('machine-mode');workspace.scrollIntoView({behavior:'smooth',block:'start'})});document.getElementById('changeCustomerCodeTop')?.addEventListener('click',()=>renderCodeGate());bindMachineBoard(machines);startCommunicationRotation(comm);startJobCardAlertWatch()}catch(e){root.className='assigned-error';root.textContent=e.message}}
  async function bootstrap(){if(!token){location.replace('/login');return}try{const gate=await api('/api/checklist-reports/technician-customer-access');if(gate.requiresCode)renderCodeGate();else await loadAssignedCustomer()}catch(e){root.className='assigned-error';root.textContent=e.message}}
  document.getElementById('sidebarToggle')?.addEventListener('click',()=>document.getElementById('belmShell')?.classList.toggle('is-sidebar-open'));bootstrap();
})();
</script>
</body>
